mapper.select:
SELECT NVL(CONTROL_MODULE,'TTL') MODULE
,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND ABNORMAL_FKAG>0 THEN PRODSPEC_ID ELSE NULL END) ABNORMAL ,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND WIP>0 THEN PRODSPEC_ID ELSE NULL END) CONTROL_WIP ,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND WIP=0 THEN PRODSPEC_ID ELSE NULL END) CONTROL_NO_WIP ,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE<CONTROL_TIME AND WIP>0 THEN PRODSPEC_ID ELSE NULL END) NOT_CONTROL_WIP ,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE<CONTROL_TIME AND WIP=0 THEN PRODSPEC_ID ELSE NULL END) NOT_CONTROL_NO_WIP ,'/' NO_WIP ,COUNT(CASE WHEN FLOW_KEY LIKE 'B%' OR FLOW_KEY LIKE 'Y%' THEN PRODSPEC_ID ELSE NULL END) DYB_REWORK ,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND WIP>0 THEN PRODSPEC_ID ELSE NULL END)+ COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND WIP=0 THEN PRODSPEC_ID ELSE NULL END)+ COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE<CONTROL_TIME AND WIP>0 THEN PRODSPEC_ID ELSE NULL END)+ COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE<CONTROL_TIME AND WIP=0 THEN PRODSPEC_ID ELSE NULL END)+ COUNT(CASE WHEN FLOW_KEY LIKE 'B%' OR FLOW_KEY LIKE 'Y%' THEN PRODSPEC_ID ELSE NULL END) TOTAL
FROM ( SELECT CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE NOT LIKE 'Processing' THEN NVL(WAFER_QTY,0) ELSE 0 END) WIP ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME ,SUM(NVL(QTY,0)) ABNORMAL_FKAG FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE,D.QTY FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN (SELECT * FROM A3MFGYW1.V_LOT_SUMMARY WHERE (LOT_INV_STATE = 'OnFloor' OR BANK_ID = '*BANKCROSS')
AND NENG_FLAG=#{nengFlag}
AND LOCATION=#{fab} )C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE LOCATION=#{fab} AND TYPE='CONTROL' AND MAINTAIN_REASON IS NULL
AND NENG_FLAG=#{nengFlag}
)D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.FLOW_KEY=D.MAINPD_ID AND A.OPER_NO=D.OPE_NO ) GROUP BY CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ) GROUP BY ROLLUP(CONTROL_MODULE) ORDER BY DECODE(CONTROL_MODULE,'PHOTO',1,'ETCH',2,'TF',3,'DIFF',4,'WET',5,'CMP',6,'METRO',7,'OTHERS',8,9)

SELECT NVL(CONTROL_MODULE,'TTL') MODULE ,COUNT(CASE WHEN SYSDATE<CONTROL_TIME AND ABNORMAL>0 THEN PRODSPEC_ID ELSE NULL END) ABNORMAL ,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND WIP_TOTAL<0 THEN PRODSPEC_ID ELSE NULL END) WIP_NOTCLEAR ,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND WIP_TOTAL>=0 THEN PRODSPEC_ID ELSE NULL END) WIP_CLEAR ,COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND WIP_TOTAL>0 THEN PRODSPEC_ID ELSE NULL END) +COUNT(CASE WHEN FLOW_KEY NOT LIKE 'B%' AND FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>CONTROL_TIME AND WIP_TOTAL=0 THEN PRODSPEC_ID ELSE NULL END) TOTAL FROM
( SELECT PULL_MODULE CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) THEN NVL(WAFER_QTY,0) ELSE 0 END ) WIP_TOTAL ,SUM(ABNORMAL_FLAG) ABNORMAL ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE ,CASE WHEN D.PRODSPEC_ID IS NOT NULL THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END ABNORMAL_FLAG FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN (SELECT A.* FROM A3MFGYW1.V_LOT_SUMMARY A WHERE A.LOCATION=#{fab} AND (A.LOT_INV_STATE = 'OnFloor' OR A.BANK_ID = '*BANKCROSS')
AND A.NENG_FLAG=#{nengFlag}
AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID ) )C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN ( SELECT DISTINCT A.PRODSPEC_ID,A.FLOW_KEY,A.TRIGGER_OPE_NO,A.TARGET_OPE_NO FROM A1MFG.REMAIN_QTIME_LOT@A1PDW A WHERE A.LOCATION=#{fab}
AND A.NENG_FLAG=#{nengFlag}
AND SUBSTR(A.MAINPD_ID,1,1) IN ('Y','B') AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID )
)D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.FLOW_KEY=D.FLOW_KEY AND A.FROM_OPE_NO=D.TRIGGER_OPE_NO AND A.TO_OPE_NO=D.TARGET_OPE_NO ) GROUP BY PULL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ) GROUP BY ROLLUP(CONTROL_MODULE) ORDER BY DECODE(CONTROL_MODULE,'PHOTO',1,'ETCH',2,'TF',3,'DIFF',4,'WET',5,'CMP',6,'METRO',7,'OTHERS',8,9)

SELECT NVL(CONTROL_MODULE,'TTL') MODULE ,COUNT(CASE WHEN PATH_FLAG>=LOOP_CNT AND WIP_NOT_HOLD>0 AND MOVE=0 THEN PRODSPEC_ID ELSE NULL END) ABNORMAL ,COUNT(CASE WHEN PATH_FLAG>=LOOP_CNT AND WIP>0 THEN PRODSPEC_ID ELSE NULL END) LINE_PRD ,COUNT(CASE WHEN PATH_FLAG<LOOP_CNT AND WIP>0 THEN PRODSPEC_ID ELSE NULL END) NOT_LINE_PRD ,ROUND((COUNT(CASE WHEN PATH_FLAG>=LOOP_CNT AND WIP>0 THEN PRODSPEC_ID ELSE NULL END)/ CASE WHEN ( COUNT(CASE WHEN PATH_FLAG>=LOOP_CNT AND WIP>0 THEN PRODSPEC_ID ELSE NULL END)+ COUNT(CASE WHEN PATH_FLAG<LOOP_CNT AND WIP>0 THEN PRODSPEC_ID ELSE NULL END) )=0 THEN NULL ELSE ( COUNT(CASE WHEN PATH_FLAG>=LOOP_CNT AND WIP>0 THEN PRODSPEC_ID ELSE NULL END)+ COUNT(CASE WHEN PATH_FLAG<LOOP_CNT AND WIP>0 THEN PRODSPEC_ID ELSE NULL END) ) END )*100,1) LINE_PRD_RATE ,COUNT(CASE WHEN PATH_FLAG_NST>=LOOP_CNT THEN PRODSPEC_ID ELSE NULL END ) LINE_NST ,COUNT(CASE WHEN PATH_FLAG_NST<LOOP_CNT THEN PRODSPEC_ID ELSE NULL END) NOT_LINE_NST ,ROUND((COUNT(CASE WHEN PATH_FLAG_NST>=LOOP_CNT THEN PRODSPEC_ID ELSE NULL END )/ CASE WHEN ( COUNT(CASE WHEN PATH_FLAG_NST>=LOOP_CNT THEN PRODSPEC_ID ELSE NULL END )+ COUNT(CASE WHEN PATH_FLAG_NST<LOOP_CNT THEN PRODSPEC_ID ELSE NULL END) )=0 THEN NULL ELSE ( COUNT(CASE WHEN PATH_FLAG_NST>=LOOP_CNT THEN PRODSPEC_ID ELSE NULL END )+ COUNT(CASE WHEN PATH_FLAG_NST<LOOP_CNT THEN PRODSPEC_ID ELSE NULL END) ) END )*100,1) LINE_NST_RATE ,COUNT(CASE WHEN PATH_FLAG_NST>=LOOP_CNT THEN PRODSPEC_ID ELSE NULL END )+ COUNT(CASE WHEN PATH_FLAG_NST<LOOP_CNT THEN PRODSPEC_ID ELSE NULL END) TOTAL FROM ( SELECT CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN OPER_NO=CONTINUS_ENTRY_OPE_NO THEN NVL(WAFER_QTY,0) ELSE 0 END) WIP ,SUM(CASE WHEN OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE<>'OnHold' THEN NVL(WAFER_QTY,0) ELSE 0 END) WIP_NOT_HOLD ,SUM(CASE WHEN OPER_NO=CONTINUS_ENTRY_OPE_NO THEN NVL(MOVE,0) ELSE 0 END) MOVE ,MAX(PRD_CNT) PATH_FLAG ,MAX(NST_CNT) PATH_FLAG_NST ,MAX(LOOP_CNT) LOOP_CNT FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE,D.WAFER_QTY MOVE FROM ( SELECT * FROM A1_MFG.SUIXIU_QLOOP_INFO_MFG A WHERE A.LOCATION='N1A1' AND A.FLOW_KEY NOT LIKE 'B%' AND A.FLOW_KEY NOT LIKE 'Y%' AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PUSH' )B WHERE A.FLOW_KEY=B.LOT_ID AND A.PRODSPEC_ID=B.PRODSPEC_ID AND A.CONTINUS_ENTRY_OPE_NO=B.OPE_NO AND A.CONTINUS_TARGET_OPE_NO=B.NENG_FLAG ) )A LEFT JOIN (SELECT * FROM A3MFGYW1.V_LOT_SUMMARY WHERE LOCATION='N1A1' AND (LOT_INV_STATE = 'OnFloor' OR BANK_ID = '*BANKCROSS')
AND NENG_FLAG=#{nengFlag}
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN ( SELECT * FROM A3MFGYW1.MOVE_SUMMARY WHERE LOCATION='N1A1' AND MOVE_FLAG='1' AND COMPLETE_TIME>TO_DATE('2026-04-15 12:00:00','YYYY-MM-DD HH24:MI:SS')
AND NENG_FLAG=#{nengFlag}
)D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.OPER_NO=D.OPE_NO ) GROUP BY CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ) GROUP BY ROLLUP(CONTROL_MODULE) ORDER BY DECODE(CONTROL_MODULE,'PHOTO',1,'ETCH',2,'TF',3,'DIFF',4,'WET',5,'CMP',6,'METRO',7,'OTHERS',8,9)

SELECT CASE WHEN #{type}='ABNORMAL' AND F.TYPE1='ABNORMAL' THEN '控货异常' WHEN SYSDATE > F.CONTROL_TIME THEN '已到控货时间' WHEN SYSDATE <F.CONTROL_TIME THEN '未到控货时间' END CONTROL_RTD ,CASE WHEN SYSDATE>F.CONTROL_TIME AND SYSDATE>F.CONTROL_TIME_INLINE THEN '控货' WHEN SYSDATE<F.CONTROL_TIME AND SYSDATE>F.CONTROL_TIME_INLINE THEN 'INLINE控货' WHEN SYSDATE>F.CONTROL_TIME AND SYSDATE<F.CONTROL_TIME_INLINE THEN 'STD控货' WHEN SYSDATE<F.CONTROL_TIME AND SYSDATE<F.CONTROL_TIME_INLINE THEN '未到控货时间' END CONTROL_FLAG ,F.CONTROL_MODULE,F.PRODG1,F.PRODSPEC_ID,F.FLOW_KEY,F.CONTINUS_ENTRY_OPE_NO,F.CONTINUS_TARGET_OPE_NO,F.TECH,F.TYPE ,F.DEADLINE,F.CT,F.INLINE_CT,F.WIP,F.DIFF,F.DIFF_INLINE,F.FROM_EQP_G,F.TO_EQP_G,F.CONTROL_TIME,F.FORECAST_TIME_CONTROL ,F.CONTROL_TIME_INLINE,F.FORECAST_TIME_PULL,F.FORECAST_TIME_PULL_INLINE,F.TYPE1 FROM ( SELECT CASE --WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.ABNORMAL_FKAG>0 THEN 'ABNORMAL' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP>0 THEN 'CONTROL_WIP' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP=0 THEN 'CONTROL_NO_WIP' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE<E.CONTROL_TIME AND E.WIP>0 THEN 'NOT_CONTROL_WIP' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE<E.CONTROL_TIME AND E.WIP=0 THEN 'NOT_CONTROL_NO_WIP' WHEN E.FLOW_KEY LIKE 'B%' OR E.FLOW_KEY LIKE 'Y%' THEN 'DYB_REWORK' END TYPE, CASE WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.ABNORMAL_FKAG>0 THEN 'ABNORMAL' ELSE NULL END TYPE1 ,E.CONTROL_MODULE,E.PRODG1,E.PRODSPEC_ID,E.FLOW_KEY,E.CONTINUS_ENTRY_OPE_NO,E.CONTINUS_TARGET_OPE_NO ,E.TECH,E.DEADLINE,E.CT,E.INLINE_CT ,CASE WHEN #{type}='ABNORMAL' THEN NVL(D.WIP,0) ELSE E.WIP END WIP ,E.DIFF,E.DIFF_INLINE ,E.FROM_EQP_G,E.TO_EQP_G,E.CONTROL_TIME,E.FORECAST_TIME_CONTROL,E.CONTROL_TIME_INLINE,E.FORECAST_TIME_PULL ,E.FORECAST_TIME_PULL_INLINE FROM ( SELECT CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE <> 'Processing' THEN NVL(WAFER_QTY,0) ELSE 0 END) WIP ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME ,MAX(TO_DATE(CONTROL_TIME_INLINE,'YYYY/MM/DD HH24:MI')) CONTROL_TIME_INLINE ,SUM(NVL(CONTROL_ABNORMAL_MOVE,0))+SUM(NVL(CONTROL_ABNORMAL_DYB,0)) ABNORMAL_FKAG ,MAX(TECH) TECH ,MAX(DEADLINE) DEADLINE ,MAX(CT_ACC) CT ,MAX(INLINE_CT_ACC) INLINE_CT ,MAX(DIFF_CONTROL) DIFF ,MAX(DIFF_CONTROL_INLINE) DIFF_INLINE ,MAX(FROM_EQP_G) FROM_EQP_G ,MAX(TO_EQP_G) TO_EQP_G ,MAX(TO_DATE(FORECAST_TIME_CONTROL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_CONTROL ,MAX(TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL ,MAX(TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL_INLINE FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN (SELECT * FROM A3MFGYW1.V_LOT_SUMMARY WHERE LOCATION=#{fab} AND (LOT_INV_STATE = 'OnFloor' OR BANK_ID = '*BANKCROSS')
AND NENG_FLAG=#{nengFlag}
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO ) GROUP BY CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO )E LEFT JOIN ( SELECT PRODSPEC_ID,MAINPD_ID,OPE_NO,SUM(QTY) WIP FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE LOCATION=#{fab} AND TYPE='CONTROL' AND MAINTAIN_REASON IS NULL
AND NENG_FLAG=#{nengFlag}
GROUP BY PRODSPEC_ID,MAINPD_ID,OPE_NO )D ON E.PRODSPEC_ID=D.PRODSPEC_ID AND E.FLOW_KEY=D.MAINPD_ID AND E.CONTINUS_ENTRY_OPE_NO=D.OPE_NO
)F WHERE 1=1
AND F.CONTROL_MODULE=#{module}
AND
(
F.TYPE=#{type}
OR F.TYPE1='ABNORMAL')
ORDER BY F.WIP DESC

SELECT CASE WHEN SYSDATE > F.CONTROL_TIME THEN '已到控货时间' WHEN SYSDATE <F.CONTROL_TIME THEN '未到控货时间' END CONTROL_RTD ,CASE WHEN F.FLAG_PULL='3' THEN '正常可穿出' WHEN F.FLAG_PULL='2' THEN '无法穿出' END PULL_RTD ,CASE WHEN F.FLAG_PULL='2' THEN '无法穿出' WHEN F.FLAG_PULL='3' THEN '正常可穿出' END PULL_FLAG ,F.TYPE,F.TYPE1,F.CONTROL_MODULE,F.PRODG1,F.PRODSPEC_ID,F.FLOW_KEY,F.CONTINUS_ENTRY_OPE_NO,F.CONTINUS_TARGET_OPE_NO ,CASE WHEN #{type}='ABNORMAL' THEN F.WIP_AB ELSE F.WIP_TOTAL END WIP ,F.ABNORMAL,F.CONTROL_TIME,F.TECH,F.DEADLINE,F.CT,F.INLINE_CT,F.DIFF,F.DIFF_INLINE,F.FROM_EQP_G,F.TO_EQP_G ,F.FORECAST_TIME_CONTROL,F.FORECAST_TIME_PULL,F.FORECAST_TIME_PULL_INLINE,F.CONTROL_TIME_INLINE FROM ( SELECT CASE WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL>0 THEN 'WIP_NOTCLEAR' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL=0 THEN 'WIP_CLEAR' END TYPE ,CASE WHEN SYSDATE>E.CONTROL_TIME AND E.ABNORMAL>0 THEN 'ABNORMAL' END TYPE1 ,E.CONTROL_MODULE,E.PRODG1,E.PRODSPEC_ID,E.FLOW_KEY,E.CONTINUS_ENTRY_OPE_NO,E.CONTINUS_TARGET_OPE_NO,E.WIP_TOTAL,E.WIP_AB,E.ABNORMAL ,E.CONTROL_TIME,E.TECH,E.DEADLINE,E.CT,E.INLINE_CT,E.DIFF,E.DIFF_INLINE,E.FROM_EQP_G,E.TO_EQP_G,E.FORECAST_TIME_CONTROL ,E.FORECAST_TIME_PULL,E.FORECAST_TIME_PULL_INLINE,E.CONTROL_TIME_INLINE,E.FLAG_PULL FROM ( SELECT PULL_MODULE CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) THEN NVL(WAFER_QTY,0) ELSE 0 END ) WIP_TOTAL ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) AND (STD_FLAG=1 OR HOLD_FLAG=1 OR NOT_RUN_FLAG=1) THEN NVL(WAFER_QTY,0) ELSE 0 END ) +SUM(NVL(B_QTY,0)) WIP_AB ,SUM(ABNORMAL_FLAG) ABNORMAL ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME ,MAX(TECH) TECH ,MAX(TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) DEADLINE ,MAX(CT_ACC) CT ,MAX(INLINE_CT_ACC) INLINE_CT ,MAX(DIFF_CONTROL) DIFF ,MAX(DIFF_CONTROL_INLINE) DIFF_INLINE ,MAX(FROM_EQP_G) FROM_EQP_G ,MAX(TO_EQP_G) TO_EQP_G ,MAX(TO_DATE(FORECAST_TIME_CONTROL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_CONTROL ,MAX(TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL ,MAX(TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL_INLINE ,MAX(TO_DATE(CONTROL_TIME_INLINE,'YYYY/MM/DD HH24:MI')) CONTROL_TIME_INLINE ,MAX(FLAG_PULL) FLAG_PULL FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE ,CASE WHEN ROW_NUMBER() OVER(PARTITION BY A.PRODSPEC_ID,A.FLOW_KEY,A.CONTINUS_ENTRY_OPE_NO,A.CONTINUS_TARGET_OPE_NO,A.FROM_OPE_NO,A.TO_OPE_NO ORDER BY A.OPER_SEQ) =1 THEN D.B_QTY ELSE NULL END B_QTY ,CASE WHEN D.PRODSPEC_ID IS NOT NULL THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END ABNORMAL_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END HOLD_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 ELSE 0 END STD_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) THEN 1 ELSE 0 END NOT_RUN_FLAG ,CASE WHEN D.B_QTY IS NOT NULL THEN 1 ELSE 0 END B_FLAG ,CASE WHEN C.LOT_ID IS NOT NULL AND TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')<TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') AND TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')<TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') THEN '3' WHEN C.LOT_ID IS NOT NULL AND TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') THEN '2' END FLAG_PULL FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN ( SELECT * FROM A3MFGYW1.V_LOT_SUMMARY A WHERE A.LOCATION=#{fab} AND (A.LOT_INV_STATE = 'OnFloor' OR A.BANK_ID = '*BANKCROSS')
AND A.NENG_FLAG=#{nengFlag}
AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID )
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN (
SELECT PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO,SUM(WAFER_QTY) B_QTY FROM ( SELECT A.* FROM A1MFG.REMAIN_QTIME_LOT@A1PDW A WHERE A.LOCATION=#{fab}
AND A.NENG_FLAG=#{nengFlag}
AND SUBSTR(A.MAINPD_ID,1,1) IN ('Y','B') AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID ) ) GROUP BY PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO )D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.FLOW_KEY=D.FLOW_KEY AND A.FROM_OPE_NO=D.TRIGGER_OPE_NO AND A.TO_OPE_NO=D.TARGET_OPE_NO ) GROUP BY PULL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO )E )F WHERE 1=1 --AND TYPE IS NOT NULL
AND CONTROL_MODULE=#{module}
AND
(
F.TYPE=#{type}
OR F.TYPE1='ABNORMAL')
AND TYPE1 IS NOT NULL
AND TYPE IS NOT NULL
UNION ALL
SELECT NULL CONTROL_RTD,NULL PULL_RTD,NULL PULL_FLAG,NULL TYPE,NULL TYPE1,NULL CONTROL_MODULE,NULL PRODG1,NULL PRODSPEC_ID,NULL FLOW_KEY ,NULL CONTINUS_ENTRY_OPE_NO,NULL CONTINUS_TARGET_OPE_NO ,SUM(WIP) WIP,NULL ABNORMAL,NULL CONTROL_TIME,NULL TECH,NULL DEADLINE,NULL CT,NULL INLINE_CT,NULL DIFF,NULL DIFF_INLINE ,NULL FROM_EQP_G,NULL TO_EQP_G,NULL FORECAST_TIME_CONTROL,NULL FORECAST_TIME_PULL,NULL FORECAST_TIME_PULL_INLINE,NULL CONTROL_TIME_INLINE FROM (
SELECT CASE WHEN SYSDATE > F.CONTROL_TIME THEN '已到控货时间' WHEN SYSDATE <F.CONTROL_TIME THEN '未到控货时间' END CONTROL_RTD ,CASE WHEN F.FLAG_PULL='3' THEN '正常可穿出' WHEN F.FLAG_PULL='2' THEN '无法穿出' END PULL_RTD ,CASE WHEN F.FLAG_PULL='2' THEN '无法穿出' WHEN F.FLAG_PULL='3' THEN '正常可穿出' END PULL_FLAG ,F.TYPE,F.TYPE1,F.CONTROL_MODULE,F.PRODG1,F.PRODSPEC_ID,F.FLOW_KEY,F.CONTINUS_ENTRY_OPE_NO,F.CONTINUS_TARGET_OPE_NO ,CASE WHEN #{type}='ABNORMAL' THEN F.WIP_AB ELSE F.WIP_TOTAL END WIP ,F.ABNORMAL,F.CONTROL_TIME,F.TECH,F.DEADLINE,F.CT,F.INLINE_CT,F.DIFF,F.DIFF_INLINE,F.FROM_EQP_G,F.TO_EQP_G ,F.FORECAST_TIME_CONTROL,F.FORECAST_TIME_PULL,F.FORECAST_TIME_PULL_INLINE,F.CONTROL_TIME_INLINE FROM ( SELECT CASE WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL>0 THEN 'WIP_NOTCLEAR' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL=0 THEN 'WIP_CLEAR' END TYPE ,CASE WHEN SYSDATE>E.CONTROL_TIME AND E.ABNORMAL>0 THEN 'ABNORMAL' END TYPE1 ,E.CONTROL_MODULE,E.PRODG1,E.PRODSPEC_ID,E.FLOW_KEY,E.CONTINUS_ENTRY_OPE_NO,E.CONTINUS_TARGET_OPE_NO,E.WIP_TOTAL,E.WIP_AB,E.ABNORMAL ,E.CONTROL_TIME,E.TECH,E.DEADLINE,E.CT,E.INLINE_CT,E.DIFF,E.DIFF_INLINE,E.FROM_EQP_G,E.TO_EQP_G,E.FORECAST_TIME_CONTROL ,E.FORECAST_TIME_PULL,E.FORECAST_TIME_PULL_INLINE,E.CONTROL_TIME_INLINE,E.FLAG_PULL FROM ( SELECT PULL_MODULE CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) THEN NVL(WAFER_QTY,0) ELSE 0 END ) WIP_TOTAL ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) AND (STD_FLAG=1 OR HOLD_FLAG=1 OR NOT_RUN_FLAG=1) THEN NVL(WAFER_QTY,0) ELSE 0 END ) +SUM(NVL(B_QTY,0)) WIP_AB ,SUM(ABNORMAL_FLAG) ABNORMAL ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME ,MAX(TECH) TECH ,MAX(TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) DEADLINE ,MAX(CT_ACC) CT ,MAX(INLINE_CT_ACC) INLINE_CT ,MAX(DIFF_CONTROL) DIFF ,MAX(DIFF_CONTROL_INLINE) DIFF_INLINE ,MAX(FROM_EQP_G) FROM_EQP_G ,MAX(TO_EQP_G) TO_EQP_G ,MAX(TO_DATE(FORECAST_TIME_CONTROL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_CONTROL ,MAX(TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL ,MAX(TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL_INLINE ,MAX(TO_DATE(CONTROL_TIME_INLINE,'YYYY/MM/DD HH24:MI')) CONTROL_TIME_INLINE ,MAX(FLAG_PULL) FLAG_PULL FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE ,CASE WHEN ROW_NUMBER() OVER(PARTITION BY A.PRODSPEC_ID,A.FLOW_KEY,A.CONTINUS_ENTRY_OPE_NO,A.CONTINUS_TARGET_OPE_NO,A.FROM_OPE_NO,A.TO_OPE_NO ORDER BY A.OPER_SEQ) =1 THEN D.B_QTY ELSE NULL END B_QTY ,CASE WHEN D.PRODSPEC_ID IS NOT NULL THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND(SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END ABNORMAL_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END HOLD_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 ELSE 0 END STD_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) THEN 1 ELSE 0 END NOT_RUN_FLAG ,CASE WHEN D.B_QTY IS NOT NULL THEN 1 ELSE 0 END B_FLAG ,CASE WHEN C.LOT_ID IS NOT NULL AND TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')<TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') AND TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')<TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') THEN '3' WHEN C.LOT_ID IS NOT NULL AND TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') THEN '2' END FLAG_PULL FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN ( SELECT * FROM A3MFGYW1.V_LOT_SUMMARY A WHERE A.LOCATION=#{fab} AND (A.LOT_INV_STATE = 'OnFloor' OR A.BANK_ID = '*BANKCROSS')
AND A.NENG_FLAG=#{nengFlag}
AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID )
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN (
SELECT PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO,SUM(WAFER_QTY) B_QTY FROM ( SELECT A.* FROM A1MFG.REMAIN_QTIME_LOT@A1PDW A WHERE A.LOCATION=#{fab}
AND A.NENG_FLAG=#{nengFlag}
AND SUBSTR(A.MAINPD_ID,1,1) IN ('Y','B') AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID ) ) GROUP BY PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO )D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.FLOW_KEY=D.FLOW_KEY AND A.FROM_OPE_NO=D.TRIGGER_OPE_NO AND A.TO_OPE_NO=D.TARGET_OPE_NO ) GROUP BY PULL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO )E )F WHERE 1=1 --AND TYPE IS NOT NULL
AND CONTROL_MODULE=#{module}
AND
(
F.TYPE=#{type}
OR F.TYPE1='ABNORMAL')
AND TYPE1 IS NOT NULL
AND TYPE IS NOT NULL
)

SELECT F.CONTROL_MODULE,F.PRODSPEC_ID,F.CONTINUS_ENTRY_OPE_NO,F.CONTINUS_TARGET_OPE_NO ,F.PRODG1,F.TECH,F.DEADLINE,F.CT,F.INLINE_CT,F.WIP,F.DIFF,F.DIFF_INLINE ,F.FROM_EQP_G,F.TO_EQP_G,F.FLOW_KEY,F.CONTROL_TIME,F.FORECAST_TIME_PULL ,F.LIST_PRD,F.LIST_NST FROM ( SELECT E.CONTROL_MODULE,E.CONTROL_TIME,TO_CHAR(SYSDATE+E.CT/24,'YYYY-MM-DD HH24:MI') FORECAST_TIME_PULL ,E.PRODG1,E.PRODSPEC_ID,E.CONTINUS_ENTRY_OPE_NO,E.CONTINUS_TARGET_OPE_NO ,E.TECH,E.DEADLINE,E.CT,E.INLINE_CT,E.WIP,E.DIFF,E.DIFF_INLINE,E.FLOW_KEY ,E.FROM_EQP_G,E.TO_EQP_G ,CASE WHEN PATH_FLAG>=LOOP_CNT AND WIP_NOT_HOLD>0 AND MOVE=0 THEN 'ABNORMAL' ELSE '' END TYPE ,CASE WHEN PATH_FLAG>=LOOP_CNT AND WIP>0 THEN 'LINE_PRD' WHEN PATH_FLAG<LOOP_CNT AND WIP>0 THEN 'NOT_LINE_PRD' ELSE '' END TYPE1 ,CASE WHEN PATH_FLAG_NST>=LOOP_CNT THEN 'LINE_NST' WHEN PATH_FLAG_NST<LOOP_CNT THEN 'NOT_LINE_NST' ELSE '' END TYPE2 ,E.LIST_PRD,E.LIST_NST FROM ( SELECT CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,MAX(TECH) TECH ,MAX(DEADLINE) DEADLINE ,MAX(CT_ACC) CT ,MAX(INLINE_CT_ACC) INLINE_CT ,MAX(DIFF_CONTROL) DIFF ,MAX(DIFF_CONTROL_INLINE) DIFF_INLINE ,MAX(FROM_EQP_G) FROM_EQP_G ,MAX(TO_EQP_G) TO_EQP_G ,SUM(CASE WHEN OPER_NO=CONTINUS_ENTRY_OPE_NO THEN NVL(WAFER_QTY,0) ELSE 0 END) WIP ,SUM(CASE WHEN OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE<>'OnHold' THEN NVL(WAFER_QTY,0) ELSE 0 END) WIP_NOT_HOLD ,SUM(CASE WHEN OPER_NO=CONTINUS_ENTRY_OPE_NO THEN NVL(MOVE,0) ELSE 0 END) MOVE ,MAX(PRD_CNT) PATH_FLAG ,MAX(NST_CNT) PATH_FLAG_NST ,MAX(LOOP_CNT) LOOP_CNT ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME ,MAX(TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL ,LISTAGG(DISTINCT CASE WHEN PATH_FLAG = 0 THEN OPER_NO END, ',') WITHIN GROUP (ORDER BY OPER_NO) AS LIST_PRD ,LISTAGG(DISTINCT CASE WHEN PATH_FLAG_NST = 0 THEN OPER_NO END, ',') WITHIN GROUP (ORDER BY OPER_NO) AS LIST_NST FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE,D.WAFER_QTY MOVE,C.FAB FROM ( SELECT * FROM A1_MFG.SUIXIU_QLOOP_INFO_MFG A WHERE A.LOCATION='N1A1' AND A.FLOW_KEY NOT LIKE 'B%' AND A.FLOW_KEY NOT LIKE 'Y%' AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PUSH' )B WHERE A.FLOW_KEY=B.LOT_ID AND A.PRODSPEC_ID=B.PRODSPEC_ID AND A.CONTINUS_ENTRY_OPE_NO=B.OPE_NO AND A.CONTINUS_TARGET_OPE_NO=B.NENG_FLAG ) )A LEFT JOIN (SELECT * FROM A3MFGYW1.V_LOT_SUMMARY WHERE LOCATION='N1A1' AND (LOT_INV_STATE = 'OnFloor' OR BANK_ID = '*BANKCROSS')
AND NENG_FLAG= #{nengFlag}
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN ( SELECT * FROM A3MFGYW1.MOVE_SUMMARY WHERE LOCATION='N1A1' AND MOVE_FLAG='1' AND COMPLETE_TIME>TO_DATE('2026-04-15 12:00:00','YYYY-MM-DD HH24:MI:SS')
AND NENG_FLAG= #{nengFlag}
)D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.OPER_NO=D.OPE_NO ) GROUP BY CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO )E )F WHERE 1=1
AND CONTROL_MODULE=#{module}
AND (TYPE=#{type} OR TYPE1=#{type} OR TYPE2=#{type})

SELECT CASE WHEN #{type}='ABNORMAL' THEN '控货异常' WHEN SYSDATE > F.CONTROL_TIME THEN '已到控货时间' WHEN SYSDATE <F.CONTROL_TIME THEN '未到控货时间' END CONTROL_RTD ,CASE WHEN SYSDATE>F.CONTROL_TIME AND SYSDATE>F.CONTROL_TIME_INLINE THEN '控货' WHEN SYSDATE<F.CONTROL_TIME AND SYSDATE>F.CONTROL_TIME_INLINE THEN 'INLINE控货' WHEN SYSDATE>F.CONTROL_TIME AND SYSDATE<F.CONTROL_TIME_INLINE THEN 'STD控货' WHEN SYSDATE<F.CONTROL_TIME AND SYSDATE<F.CONTROL_TIME_INLINE THEN '未到控货时间' END CONTROL_FLAG ,CASE WHEN FORECAST_TIME_PULL>DEADLINE AND FORECAST_TIME_PULL_INLINE>DEADLINE THEN '无法穿出' WHEN FORECAST_TIME_PULL>DEADLINE AND FORECAST_TIME_PULL_INLINE<DEADLINE THEN 'STD无法穿出' WHEN FORECAST_TIME_PULL<DEADLINE AND FORECAST_TIME_PULL_INLINE>DEADLINE THEN 'INLNE无法穿出' WHEN FORECAST_TIME_PULL<DEADLINE AND FORECAST_TIME_PULL_INLINE<DEADLINE THEN '正常穿出' END PULL_FLAG
,F.* FROM ( SELECT CONTROL_MODULE,MODULE,PULL_MODULE,PRODG1,PRODSPEC_ID ,CONTINUS_ENTRY_OPE_NO FROM_OPE_NO,CONTINUS_TARGET_OPE_NO TO_OPE_NO ,LOT_ID,WAFER_QTY,LOT_PROC_STATE,CT_ACC CT,INLINE_CT_ACC INLINE_CT,OPER_NO ,FLOW_KEY ,TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI') CONTROL_TIME ,TO_DATE(CONTROL_TIME_INLINE,'YYYY/MM/DD HH24:MI') CONTROL_TIME_INLINE ,TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI') FORECAST_TIME_PULL ,TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI') FORECAST_TIME_PULL_INLINE ,TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') DEADLINE ,ROUND((SYSDATE-LAST_OPE_COMP_TIME)*24,1) STAY_TIME ,LOT_PRIORITY,HOLD_MODULE,HOLD_COMMENT FROM ( SELECT A.* ,C.LOT_ID,C.WAFER_QTY,C.LOT_PROC_STATE,C.LOT_PRIORITY,C.MODULE HOLD_MODULE,C.HOLD_COMMENT ,C.LAST_OPE_COMP_TIME FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN ( SELECT * FROM ( SELECT A.*,B.LOT_PRIORITY ,CASE WHEN C.HOLD_COMMENT LIKE '||%' AND C.HOLD_COMMENT NOT LIKE '|||%' THEN SUBSTR(C.HOLD_COMMENT,3,4) ELSE C.MODULE END MODULE ,C.HOLD_COMMENT FROM A3MFGYW1.V_LOT_SUMMARY A LEFT JOIN PWEB.A3_LOT_PRIORITY@A1PDW B ON A.LOT_ID =B.LOT_ID LEFT JOIN (SELECT * FROM A3MFGYW1.V_HOLD_SUMMARY WHERE RELEASE_FLAG='0' AND HOLD_TYPE NOT LIKE 'BankHold')C ON A.LOT_ID =C.LOT_ID ) WHERE LOCATION=#{fab} AND (LOT_INV_STATE = 'OnFloor' OR BANK_ID = '*BANKCROSS')
AND NENG_FLAG=#{nengFlag}
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO ) WHERE 1=1 AND LOT_ID IS NOT NULL
AND PRODSPEC_ID=#{prodspecId} AND CONTINUS_ENTRY_OPE_NO=#{fromope} AND CONTINUS_TARGET_OPE_NO=#{toope}
AND OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE <> 'Processing'
AND ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO)
AND ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO)
AND (PRODSPEC_ID,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO) IN ( SELECT PRODSPEC_ID,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO FROM (
SELECT CASE WHEN SYSDATE > F.CONTROL_TIME THEN '已到控货时间' WHEN SYSDATE <F.CONTROL_TIME THEN '未到控货时间' END CONTROL_RTD ,CASE WHEN F.FORECAST_TIME_PULL<F.DEADLINE THEN '正常可穿出' WHEN F.FORECAST_TIME_PULL>F.DEADLINE THEN '无法穿出' END PULL_RTD ,CASE WHEN F.FORECAST_TIME_PULL_INLINE>F.DEADLINE OR F.FORECAST_TIME_PULL>F.DEADLINE THEN '无法穿出' WHEN F.FORECAST_TIME_PULL_INLINE<F.DEADLINE OR F.FORECAST_TIME_PULL<F.DEADLINE THEN '正常可穿出' END PULL_FLAG ,F.TYPE,F.TYPE1,F.CONTROL_MODULE,F.PRODG1,F.PRODSPEC_ID,F.FLOW_KEY,F.CONTINUS_ENTRY_OPE_NO,F.CONTINUS_TARGET_OPE_NO ,F.WIP_TOTAL WIP,F.ABNORMAL,F.CONTROL_TIME,F.TECH,F.DEADLINE,F.CT,F.INLINE_CT,F.DIFF,F.DIFF_INLINE,F.FROM_EQP_G,F.TO_EQP_G ,F.FORECAST_TIME_CONTROL,F.FORECAST_TIME_PULL,F.FORECAST_TIME_PULL_INLINE,F.CONTROL_TIME_INLINE FROM ( SELECT CASE WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL>0 THEN 'WIP_NOTCLEAR' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL=0 THEN 'WIP_CLEAR' END TYPE ,CASE WHEN SYSDATE>E.CONTROL_TIME AND E.ABNORMAL>0 THEN 'ABNORMAL' END TYPE1 ,E.CONTROL_MODULE,E.PRODG1,E.PRODSPEC_ID,E.FLOW_KEY,E.CONTINUS_ENTRY_OPE_NO,E.CONTINUS_TARGET_OPE_NO,E.WIP_TOTAL,E.ABNORMAL ,E.CONTROL_TIME,E.TECH,E.DEADLINE,E.CT,E.INLINE_CT,E.DIFF,E.DIFF_INLINE,E.FROM_EQP_G,E.TO_EQP_G,E.FORECAST_TIME_CONTROL ,E.FORECAST_TIME_PULL,E.FORECAST_TIME_PULL_INLINE,E.CONTROL_TIME_INLINE FROM ( SELECT PULL_MODULE CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) THEN NVL(WAFER_QTY,0) ELSE 0 END ) WIP_TOTAL ,SUM(ABNORMAL_FLAG) ABNORMAL ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME ,MAX(TECH) TECH ,MAX(TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) DEADLINE ,MAX(CT_ACC) CT ,MAX(INLINE_CT_ACC) INLINE_CT ,MAX(DIFF_CONTROL) DIFF ,MAX(DIFF_CONTROL_INLINE) DIFF_INLINE ,MAX(FROM_EQP_G) FROM_EQP_G ,MAX(TO_EQP_G) TO_EQP_G ,MAX(TO_DATE(FORECAST_TIME_CONTROL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_CONTROL ,MAX(TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL ,MAX(TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL_INLINE ,MAX(TO_DATE(CONTROL_TIME_INLINE,'YYYY/MM/DD HH24:MI')) CONTROL_TIME_INLINE FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE ,CASE WHEN D.PRODSPEC_ID IS NOT NULL THEN 1 WHEN (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END ABNORMAL_FLAG FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN (SELECT * FROM A3MFGYW1.V_LOT_SUMMARY WHERE LOCATION=#{fab} AND (LOT_INV_STATE = 'OnFloor' OR BANK_ID = '*BANKCROSS')
AND NENG_FLAG=#{nengFlag}
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN ( SELECT DISTINCT PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO FROM A1MFG.REMAIN_QTIME_LOT@A1PDW WHERE LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
AND SUBSTR(MAINPD_ID,1,1) IN ('Y','B') )D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.FLOW_KEY=D.FLOW_KEY AND A.FROM_OPE_NO=D.TRIGGER_OPE_NO AND A.TO_OPE_NO=D.TARGET_OPE_NO ) GROUP BY PULL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO )E )F WHERE 1=1 --AND TYPE IS NOT NULL
AND CONTROL_MODULE=#{module}
AND
(
F.TYPE=#{type}
OR F.TYPE1='ABNORMAL')
AND TYPE1 IS NOT NULL
AND TYPE IS NOT NULL
) )
)F ORDER BY F.LOT_ID

select.if:
SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='CONTROL' AND LOCATION=#{fab}
AND PRODSPEC_ID=#{prodspecId} AND OPE_NO=#{fromope}
AND MAINTAIN_REASON IS NULL

    AND NENG_FLAG=#{nengFlag}

ORDER BY CLAIM_TIME DESC

SELECT LOCATION,TECH,PRODG1,PRODSPEC_ID,FLOW_KEY,OPER_NO,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,CONTROL_MODULE,PULL_MODULE,MODULE,LOT_ID,WAFER_QTY,LOT_PROC_STATE,LOT_PRIORITY,HOLD_MODULE,HOLD_COMMENT ,PULL_TYPE1||PULL_TYPE2||PULL_TYPE3||PULL_TYPE4 PULL_TYPE,DEADLINE,FORECAST_TIME_PULL,FORECAST_TIME_PULL_INLINE,ROUND((SYSDATE-LAST_OPE_COMP_TIME)*24,1) STAY_TIME ,CONTROL_TIME,NENG_FLAG FROM ( SELECT A.LOCATION,A.TECH,A.FROM_EQP_G,A.TO_EQP_G,A.CONTROL_MODULE,A.PULL_MODULE,A.MODULE,A.PRODG1 ,A.PRODSPEC_ID,A.FLOW_KEY,A.FROM_OPE_NO,A.TO_OPE_NO,A.OPER_NO,A.CONTINUS_ENTRY_OPE_NO,A.CONTINUS_TARGET_OPE_NO ,A.DEADLINE,A.CONTROL_TIME,A.FORECAST_TIME_PULL,A.FORECAST_TIME_PULL_INLINE ,C.LOT_ID,C.WAFER_QTY,C.LOT_PROC_STATE,C.LOT_PRIORITY,C.MODULE HOLD_MODULE,C.HOLD_COMMENT ,C.LAST_OPE_COMP_TIME,C.NENG_FLAG , CASE WHEN SYSDATE>TO_DATE(A.CONTROL_TIME,'YYYY/MM/DD HH24:MI') AND OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 ELSE 0 END STAY_FLAG ,CASE WHEN SYSDATE>TO_DATE(A.CONTROL_TIME,'YYYY/MM/DD HH24:MI') AND OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END HOLD_FLAG ,CASE WHEN SYSDATE>TO_DATE(A.CONTROL_TIME,'YYYY/MM/DD HH24:MI') AND OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (TO_DATE(A.FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(A.DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(A.FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(A.DEADLINE,'YYYY/MM/DD HH24:MI')) THEN 1 ELSE 0 END NOT_RUN_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 'STAYTIME大于STD ' ELSE '' END PULL_TYPE1 ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 'QLOOP内HOLD ' ELSE '' END PULL_TYPE2 ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND TO_DATE(A.FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(A.DEADLINE,'YYYY/MM/DD HH24:MI') THEN 'STD无法穿出 ' ELSE '' END PULL_TYPE3 ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND TO_DATE(A.FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(A.DEADLINE,'YYYY/MM/DD HH24:MI') THEN 'INLINE无法穿出' ELSE '' END PULL_TYPE4
FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN ( SELECT D.* FROM ( SELECT A.*,B.LOT_PRIORITY ,CASE WHEN C.HOLD_COMMENT LIKE '||%' AND C.HOLD_COMMENT NOT LIKE '|||%' THEN SUBSTR(C.HOLD_COMMENT,3,4) ELSE C.MODULE END MODULE ,C.HOLD_COMMENT FROM ( SELECT * FROM A3MFGYW1.V_LOT_SUMMARY A AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID ) )A LEFT JOIN PWEB.A3_LOT_PRIORITY@A1PDW B ON A.LOT_ID =B.LOT_ID LEFT JOIN (SELECT * FROM A3MFGYW1.V_HOLD_SUMMARY WHERE RELEASE_FLAG='0' AND HOLD_TYPE NOT LIKE 'BankHold')C ON A.LOT_ID =C.LOT_ID )D WHERE D.LOCATION=#{fab}
AND D.NENG_FLAG=#{nengFlag}
AND (D.LOT_INV_STATE = 'OnFloor' OR D.BANK_ID = '*BANKCROSS') AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE D.LOT_ID=B.LOT_ID )
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO )WHERE 1=1 AND (STAY_FLAG=1 OR HOLD_FLAG=1 OR NOT_RUN_FLAG=1) AND LOT_ID IS NOT NULL
AND PRODSPEC_ID=#{prodspecId} AND CONTINUS_ENTRY_OPE_NO=#{fromope} AND CONTINUS_TARGET_OPE_NO=#{toope}
AND (PRODSPEC_ID,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO) IN ( SELECT DISTINCT PRODSPEC_ID,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO FROM (
SELECT CASE WHEN SYSDATE > F.CONTROL_TIME THEN '已到控货时间' WHEN SYSDATE <F.CONTROL_TIME THEN '未到控货时间' END CONTROL_RTD ,CASE WHEN F.FLAG_PULL='3' THEN '正常可穿出' WHEN F.FLAG_PULL='2' THEN '无法穿出' END PULL_RTD ,CASE WHEN F.FLAG_PULL='2' THEN '无法穿出' WHEN F.FLAG_PULL='3' THEN '正常可穿出' END PULL_FLAG ,F.TYPE,F.TYPE1,F.CONTROL_MODULE,F.PRODG1,F.PRODSPEC_ID,F.FLOW_KEY,F.CONTINUS_ENTRY_OPE_NO,F.CONTINUS_TARGET_OPE_NO ,CASE WHEN #{type}='ABNORMAL' THEN F.WIP_AB ELSE F.WIP_TOTAL END WIP ,F.ABNORMAL,F.CONTROL_TIME,F.TECH,F.DEADLINE,F.CT,F.INLINE_CT,F.DIFF,F.DIFF_INLINE,F.FROM_EQP_G,F.TO_EQP_G ,F.FORECAST_TIME_CONTROL,F.FORECAST_TIME_PULL,F.FORECAST_TIME_PULL_INLINE,F.CONTROL_TIME_INLINE FROM ( SELECT CASE WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL>0 THEN 'WIP_NOTCLEAR' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL=0 THEN 'WIP_CLEAR' END TYPE ,CASE WHEN SYSDATE>E.CONTROL_TIME AND E.ABNORMAL>0 THEN 'ABNORMAL' END TYPE1 ,E.CONTROL_MODULE,E.PRODG1,E.PRODSPEC_ID,E.FLOW_KEY,E.CONTINUS_ENTRY_OPE_NO,E.CONTINUS_TARGET_OPE_NO,E.WIP_TOTAL,E.WIP_AB,E.ABNORMAL ,E.CONTROL_TIME,E.TECH,E.DEADLINE,E.CT,E.INLINE_CT,E.DIFF,E.DIFF_INLINE,E.FROM_EQP_G,E.TO_EQP_G,E.FORECAST_TIME_CONTROL ,E.FORECAST_TIME_PULL,E.FORECAST_TIME_PULL_INLINE,E.CONTROL_TIME_INLINE,E.FLAG_PULL FROM ( SELECT PULL_MODULE CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) THEN NVL(WAFER_QTY,0) ELSE 0 END ) WIP_TOTAL ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) AND (STD_FLAG=1 OR HOLD_FLAG=1 OR NOT_RUN_FLAG=1) THEN NVL(WAFER_QTY,0) ELSE 0 END ) +SUM(NVL(B_QTY,0)) WIP_AB ,SUM(ABNORMAL_FLAG) ABNORMAL ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME ,MAX(TECH) TECH ,MAX(TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) DEADLINE ,MAX(CT_ACC) CT ,MAX(INLINE_CT_ACC) INLINE_CT ,MAX(DIFF_CONTROL) DIFF ,MAX(DIFF_CONTROL_INLINE) DIFF_INLINE ,MAX(FROM_EQP_G) FROM_EQP_G ,MAX(TO_EQP_G) TO_EQP_G ,MAX(TO_DATE(FORECAST_TIME_CONTROL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_CONTROL ,MAX(TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL ,MAX(TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL_INLINE ,MAX(TO_DATE(CONTROL_TIME_INLINE,'YYYY/MM/DD HH24:MI')) CONTROL_TIME_INLINE ,MAX(FLAG_PULL) FLAG_PULL FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE ,CASE WHEN ROW_NUMBER() OVER(PARTITION BY A.PRODSPEC_ID,A.FLOW_KEY,A.CONTINUS_ENTRY_OPE_NO,A.CONTINUS_TARGET_OPE_NO,A.FROM_OPE_NO,A.TO_OPE_NO ORDER BY A.OPER_SEQ) =1 THEN D.B_QTY ELSE NULL END B_QTY ,CASE WHEN D.PRODSPEC_ID IS NOT NULL THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END ABNORMAL_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END HOLD_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 ELSE 0 END STD_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) THEN 1 ELSE 0 END NOT_RUN_FLAG ,CASE WHEN D.B_QTY IS NOT NULL THEN 1 ELSE 0 END B_FLAG ,CASE WHEN C.LOT_ID IS NOT NULL AND TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')<TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') AND TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')<TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') THEN '3' WHEN C.LOT_ID IS NOT NULL AND TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') THEN '2' END FLAG_PULL FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN ( SELECT * FROM A3MFGYW1.V_LOT_SUMMARY A WHERE A.LOCATION=#{fab} AND (A.LOT_INV_STATE = 'OnFloor' OR A.BANK_ID = '*BANKCROSS')
AND A.NENG_FLAG=#{nengFlag}
AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID )
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN (
SELECT PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO,SUM(WAFER_QTY) B_QTY FROM ( SELECT A.* FROM A1MFG.REMAIN_QTIME_LOT@A1PDW A WHERE A.LOCATION=#{fab}
AND A.NENG_FLAG=#{nengFlag}
AND SUBSTR(A.MAINPD_ID,1,1) IN ('Y','B') AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID ) ) GROUP BY PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO )D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.FLOW_KEY=D.FLOW_KEY AND A.FROM_OPE_NO=D.TRIGGER_OPE_NO AND A.TO_OPE_NO=D.TARGET_OPE_NO ) GROUP BY PULL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO )E )F WHERE 1=1 --AND TYPE IS NOT NULL
AND CONTROL_MODULE=#{module}
AND
(
F.TYPE=#{type}
OR F.TYPE1='ABNORMAL')
AND TYPE1 IS NOT NULL
AND TYPE IS NOT NULL
) )
UNION ALL
SELECT LOCATION,TECH,PRODG1,PRODSPEC_ID,MAINPD_ID FLOW_KEY,OPE_NO OPER_NO,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,CONTROL_MODULE,PULL_MODULE,MODULE,LOT_ID,WAFER_QTY,LOT_PROC_STATE,LOT_PRIORITY,HOLD_MODULE,HOLD_COMMENT ,'DYB_REWORK' PULL_TYPE,DEADLINE,FORECAST_TIME_PULL,FORECAST_TIME_PULL_INLINE,STAY_TIME,CONTROL_TIME,NENG_FLAG FROM ( SELECT A.LOCATION,A.TECH,A.FROM_EQP_G,A.TO_EQP_G,A.CONTROL_MODULE,A.PULL_MODULE,A.MODULE,A.PRODG1 ,A.PRODSPEC_ID,A.FLOW_KEY,A.FROM_OPE_NO,A.TO_OPE_NO,A.OPER_NO,A.CONTINUS_ENTRY_OPE_NO,A.CONTINUS_TARGET_OPE_NO ,A.DEADLINE,A.CONTROL_TIME,A.FORECAST_TIME_PULL,A.FORECAST_TIME_PULL_INLINE ,C.LOT_ID,C.WAFER_QTY,C.LOT_PROC_STATE,TO_CHAR(C.LOT_PRIORITY) LOT_PRIORITY,C.MODULE HOLD_MODULE,C.HOLD_COMMENT ,C.MAINPD_ID,C.REMAIN_QTIME,C.OPE_NO,C.STAY_TIME,TO_CHAR(C.NENG_FLAG) NENG_FLAG ,ROW_NUMBER() OVER(PARTITION BY A.LOCATION,A.PRODSPEC_ID,A.CONTINUS_ENTRY_OPE_NO,A.CONTINUS_TARGET_OPE_NO,A.FROM_OPE_NO,A.TO_OPE_NO ORDER BY C.LOT_ID) RN FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN ( SELECT D.* FROM ( SELECT A.* ,CASE WHEN C.HOLD_COMMENT LIKE '||%' AND C.HOLD_COMMENT NOT LIKE '|||%' THEN SUBSTR(C.HOLD_COMMENT,3,4) ELSE C.MODULE END MODULE ,C.HOLD_COMMENT FROM ( SELECT A.LOT_ID,A.PRODG1,A.PRODSPEC_ID,A.LOT_PROC_STATE,A.MAINPD_ID,A.WAFER_QTY,A.OPE_NO,A.TRIGGER_OPE_NO,A.TARGET_OPE_NO,A.FLOW_KEY ,A.LOT_PRIORITY,A.LOCATION,A.REMAIN_QTIME,A.STAY_TIME,A.NENG_FLAG FROM A1MFG.REMAIN_QTIME_LOT@A1PDW A WHERE A.LOCATION=#{fab} AND SUBSTR(A.MAINPD_ID,1,1) IN ('Y','B')
AND A.NENG_FLAG=#{nengFlag}
AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID ) )A LEFT JOIN (SELECT * FROM A3MFGYW1.V_HOLD_SUMMARY WHERE RELEASE_FLAG='0' AND HOLD_TYPE NOT LIKE 'BankHold')C ON A.LOT_ID =C.LOT_ID )D WHERE D.LOCATION=#{fab} )C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.FLOW_KEY=C.FLOW_KEY AND A.FROM_OPE_NO=C.TRIGGER_OPE_NO AND A.TO_OPE_NO=C.TARGET_OPE_NO ) WHERE RN=1 AND LOT_ID IS NOT NULL AND SYSDATE>TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')
AND PRODSPEC_ID=#{prodspecId} AND CONTINUS_ENTRY_OPE_NO=#{fromope} AND CONTINUS_TARGET_OPE_NO=#{toope}
AND (PRODSPEC_ID,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO) IN ( SELECT DISTINCT PRODSPEC_ID,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO FROM (
SELECT CASE WHEN SYSDATE > F.CONTROL_TIME THEN '已到控货时间' WHEN SYSDATE <F.CONTROL_TIME THEN '未到控货时间' END CONTROL_RTD ,CASE WHEN F.FLAG_PULL='3' THEN '正常可穿出' WHEN F.FLAG_PULL='2' THEN '无法穿出' END PULL_RTD ,CASE WHEN F.FLAG_PULL='2' THEN '无法穿出' WHEN F.FLAG_PULL='3' THEN '正常可穿出' END PULL_FLAG ,F.TYPE,F.TYPE1,F.CONTROL_MODULE,F.PRODG1,F.PRODSPEC_ID,F.FLOW_KEY,F.CONTINUS_ENTRY_OPE_NO,F.CONTINUS_TARGET_OPE_NO ,CASE WHEN #{type}='ABNORMAL' THEN F.WIP_AB ELSE F.WIP_TOTAL END WIP ,F.ABNORMAL,F.CONTROL_TIME,F.TECH,F.DEADLINE,F.CT,F.INLINE_CT,F.DIFF,F.DIFF_INLINE,F.FROM_EQP_G,F.TO_EQP_G ,F.FORECAST_TIME_CONTROL,F.FORECAST_TIME_PULL,F.FORECAST_TIME_PULL_INLINE,F.CONTROL_TIME_INLINE FROM ( SELECT CASE WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL>0 THEN 'WIP_NOTCLEAR' WHEN E.FLOW_KEY NOT LIKE 'B%' AND E.FLOW_KEY NOT LIKE 'Y%' AND SYSDATE>E.CONTROL_TIME AND E.WIP_TOTAL=0 THEN 'WIP_CLEAR' END TYPE ,CASE WHEN SYSDATE>E.CONTROL_TIME AND E.ABNORMAL>0 THEN 'ABNORMAL' END TYPE1 ,E.CONTROL_MODULE,E.PRODG1,E.PRODSPEC_ID,E.FLOW_KEY,E.CONTINUS_ENTRY_OPE_NO,E.CONTINUS_TARGET_OPE_NO,E.WIP_TOTAL,E.WIP_AB,E.ABNORMAL ,E.CONTROL_TIME,E.TECH,E.DEADLINE,E.CT,E.INLINE_CT,E.DIFF,E.DIFF_INLINE,E.FROM_EQP_G,E.TO_EQP_G,E.FORECAST_TIME_CONTROL ,E.FORECAST_TIME_PULL,E.FORECAST_TIME_PULL_INLINE,E.CONTROL_TIME_INLINE,E.FLAG_PULL FROM ( SELECT PULL_MODULE CONTROL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO ,SUM(CONTROL_FLAG) CONTROL_FLAG ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) THEN NVL(WAFER_QTY,0) ELSE 0 END ) WIP_TOTAL ,SUM(CASE WHEN ((OPER_NO=CONTINUS_ENTRY_OPE_NO AND LOT_PROC_STATE='Processing') OR OPER_NO<>CONTINUS_ENTRY_OPE_NO) AND (STD_FLAG=1 OR HOLD_FLAG=1 OR NOT_RUN_FLAG=1) THEN NVL(WAFER_QTY,0) ELSE 0 END ) +SUM(NVL(B_QTY,0)) WIP_AB ,SUM(ABNORMAL_FLAG) ABNORMAL ,MAX(TO_DATE(CONTROL_TIME,'YYYY/MM/DD HH24:MI')) CONTROL_TIME ,MAX(TECH) TECH ,MAX(TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) DEADLINE ,MAX(CT_ACC) CT ,MAX(INLINE_CT_ACC) INLINE_CT ,MAX(DIFF_CONTROL) DIFF ,MAX(DIFF_CONTROL_INLINE) DIFF_INLINE ,MAX(FROM_EQP_G) FROM_EQP_G ,MAX(TO_EQP_G) TO_EQP_G ,MAX(TO_DATE(FORECAST_TIME_CONTROL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_CONTROL ,MAX(TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL ,MAX(TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')) FORECAST_TIME_PULL_INLINE ,MAX(TO_DATE(CONTROL_TIME_INLINE,'YYYY/MM/DD HH24:MI')) CONTROL_TIME_INLINE ,MAX(FLAG_PULL) FLAG_PULL FROM ( SELECT A.* ,CASE WHEN a.CONTROL_RTD='red' THEN 1 ELSE 0 END CONTROL_FLAG ,C.WAFER_QTY,C.LOT_PROC_STATE ,CASE WHEN ROW_NUMBER() OVER(PARTITION BY A.PRODSPEC_ID,A.FLOW_KEY,A.CONTINUS_ENTRY_OPE_NO,A.CONTINUS_TARGET_OPE_NO,A.FROM_OPE_NO,A.TO_OPE_NO ORDER BY A.OPER_SEQ) =1 THEN D.B_QTY ELSE NULL END B_QTY ,CASE WHEN D.PRODSPEC_ID IS NOT NULL THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END ABNORMAL_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND C.LOT_PROC_STATE='OnHold' THEN 1 ELSE 0 END HOLD_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (SYSDATE-C.LAST_OPE_COMP_TIME)*24>A.CT THEN 1 ELSE 0 END STD_FLAG ,CASE WHEN OPER_NO<>CONTINUS_ENTRY_OPE_NO AND (TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI')) THEN 1 ELSE 0 END NOT_RUN_FLAG ,CASE WHEN D.B_QTY IS NOT NULL THEN 1 ELSE 0 END B_FLAG ,CASE WHEN C.LOT_ID IS NOT NULL AND TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')<TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') AND TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')<TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') THEN '3' WHEN C.LOT_ID IS NOT NULL AND TO_DATE(FORECAST_TIME_PULL,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') OR TO_DATE(FORECAST_TIME_PULL_INLINE,'YYYY/MM/DD HH24:MI')>TO_DATE(DEADLINE,'YYYY/MM/DD HH24:MI') THEN '2' END FLAG_PULL FROM ( SELECT * FROM ( SELECT T.* ,ROW_NUMBER() OVER (PARTITION BY PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO,OPER_NO ORDER BY CT DESC) RN FROM A1_MFG.SUIXIU_QLOOP_INFO T WHERE LOCATION=#{fab} ) WHERE RN=1 )A LEFT JOIN ( SELECT * FROM A3MFGYW1.V_LOT_SUMMARY A WHERE A.LOCATION=#{fab} AND (A.LOT_INV_STATE = 'OnFloor' OR A.BANK_ID = '*BANKCROSS')
AND A.NENG_FLAG=#{nengFlag}
AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID )
)C ON A.PRODSPEC_ID=C.PRODSPEC_ID AND A.OPER_NO=C.OPE_NO LEFT JOIN (
SELECT PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO,SUM(WAFER_QTY) B_QTY FROM ( SELECT A.* FROM A1MFG.REMAIN_QTIME_LOT@A1PDW A WHERE A.LOCATION=#{fab}
AND A.NENG_FLAG=#{nengFlag}
AND SUBSTR(A.MAINPD_ID,1,1) IN ('Y','B') AND NOT EXISTS ( SELECT 1 FROM ( SELECT * FROM A1_MFG.CONTROL_ABNORMAL_DETAIL WHERE TYPE='PULL' AND LOCATION=#{fab}
AND NENG_FLAG=#{nengFlag}
)B WHERE A.LOT_ID=B.LOT_ID ) ) GROUP BY PRODSPEC_ID,FLOW_KEY,TRIGGER_OPE_NO,TARGET_OPE_NO )D ON A.PRODSPEC_ID=D.PRODSPEC_ID AND A.FLOW_KEY=D.FLOW_KEY AND A.FROM_OPE_NO=D.TRIGGER_OPE_NO AND A.TO_OPE_NO=D.TARGET_OPE_NO ) GROUP BY PULL_MODULE,PRODG1,PRODSPEC_ID,FLOW_KEY,CONTINUS_ENTRY_OPE_NO,CONTINUS_TARGET_OPE_NO )E )F WHERE 1=1 --AND TYPE IS NOT NULL
AND CONTROL_MODULE=#{module}
AND
(
F.TYPE=#{type}
OR F.TYPE1='ABNORMAL')
AND TYPE1 IS NOT NULL
AND TYPE IS NOT NULL
) )
